SELECT  FROM activity
WHERE workspace_id = #{workspaceId}

  AND person_id = #{personId}


  AND deal_id = #{dealId}


  AND created_by_id = #{createdById}

ORDER BY timestamp DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM activity
WHERE workspace_id = #{workspaceId}

  AND person_id = #{personId}


  AND deal_id = #{dealId}


  AND created_by_id = #{createdById}

SELECT touch.user_id, COUNT(*) AS touches
FROM (
  SELECT a.created_by_id AS user_id
  FROM activity a
  WHERE a.workspace_id = #{workspaceId}
    AND a.timestamp >= #{startUtc}
    AND a.timestamp < #{endUtc}
  UNION ALL
  SELECT t.assigned_to_id AS user_id
  FROM task t
  WHERE t.workspace_id = #{workspaceId}
    AND t.assigned_to_id IS NOT NULL
    AND t.completed = TRUE
    AND t.updated_at >= #{startUtc}
    AND t.updated_at < #{endUtc}
  UNION ALL
  SELECT n.author_id AS user_id
  FROM note n
  WHERE n.workspace_id = #{workspaceId}
    AND n.visibility != 'private'
    AND n.created_at >= #{startUtc}
    AND n.created_at < #{endUtc}
) touch
GROUP BY touch.user_id
ORDER BY touches DESC, touch.user_id

